#!/bin/sh
# Generated by frostfire. Writes /etc/msmtprc from SMTP_* env vars so PHP's mail()
# relays straight to SendGrid (or any SMTP relay), then hands off to the stock entrypoint.
set -eu

if [ -n "${SMTP_HOST:-}" ]; then
    starttls=on
    [ "${SMTP_PORT:-587}" = "465" ] && starttls=off

    umask 027
    cat > /etc/msmtprc <<EOF
defaults
auth           on
tls            on
tls_starttls   ${starttls}
tls_trust_file /etc/ssl/certs/ca-certificates.crt

account        default
host           ${SMTP_HOST}
port           ${SMTP_PORT:-587}
user           ${SMTP_USER:-}
password       ${SMTP_PASSWORD:-}
from           ${SMTP_FROM:-}
EOF
    chown root:www-data /etc/msmtprc
    chmod 0640 /etc/msmtprc
else
    echo "frostfire: SMTP_HOST is not set, outbound mail is disabled" >&2
fi

exec docker-php-entrypoint "$@"
